<template>
  <section class="usage-panel" v-loading="loading"><div class="toolbar"><div><h2>{{ title }}</h2><p>{{ description }}</p></div></div><div v-if="usage" class="usage"><div><span>{{t('productResources.todayRequests')}}</span><strong>{{usage.requestCount}}</strong></div><div><span>{{t('productResources.remainingQuota')}}</span><strong>{{usage.remainingFree}}</strong></div><div><span>{{t('productResources.overage')}}</span><strong>{{usage.overageEnabled?t('productResources.enabledOverage'):t('productResources.disabledOverage')}}</strong></div></div><el-divider/><el-table :data="logs"><el-table-column prop="action" :label="t('productResources.actions')" min-width="180"/><el-table-column :label="t('productResources.result')" width="90"><template #default="{row}"><el-tag :type="row.success?'success':'danger'">{{row.success?t('productResources.success'):t('productResources.failed')}}</el-tag></template></el-table-column><el-table-column prop="chargeAmount" :label="t('productResources.charge')" width="100"/><el-table-column :label="t('productResources.time')" min-width="170"><template #default="{row}">{{new Date(row.createTime).toLocaleString()}}</template></el-table-column></el-table><el-empty v-if="!logs.length&&!loading" :description="t('productResources.auditEmpty')"/></section>
</template>
<script setup lang="ts">
import {ref,onMounted,watch}from 'vue';import type{DeveloperProductCode,DeveloperProductUsageDto,DeveloperProductCallLogDto}from '@/client/types.gen';import{developerProductService}from '@/service/developerProductService';import {i18ns} from '@/locales';const {t}=i18ns;const props=defineProps<{product:DeveloperProductCode;title:string;description:string}>();const loading=ref(false),usage=ref<DeveloperProductUsageDto>(),logs=ref<DeveloperProductCallLogDto[]>([]);const load=async()=>{loading.value=true;try{const[nextUsage,nextLogs]=await Promise.all([developerProductService.getUsage(props.product),developerProductService.listCallLogs(props.product)]);usage.value=nextUsage;logs.value=nextLogs}finally{loading.value=false}};watch(()=>props.product,load);onMounted(load)
</script><style scoped>.toolbar h2{margin:0 0 6px;font-size:17px}.toolbar p{margin:0;color:var(--el-text-color-secondary)}.usage{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--el-border-color-light)}.usage div{padding:14px;display:flex;flex-direction:column;gap:5px;border-right:1px solid var(--el-border-color-light)}.usage div:last-child{border:0}.usage span{color:var(--el-text-color-secondary);font-size:13px}.usage strong{font-size:20px}@media(max-width:720px){.usage{grid-template-columns:1fr}.usage div{border-right:0;border-bottom:1px solid var(--el-border-color-light)}}</style>
